// Simplified India state boundaries.
// Source: DataMeet community map data via udit-001/india-maps-data (CC BY 2.5 IN).
// Coordinates are projected once at build time into an 800 x 900 SVG viewBox.

export const MAP_VIEWBOX = { width: 800, height: 900 };

const LNG_MIN = 67.5;
const LNG_MAX = 98.0;
const LAT_MIN = 6.0;
const LAT_MAX = 37.5;
const WIDTH = 800;
const HEIGHT = 900;
const PADDING = 30;
const RAD = Math.PI / 180;

const mercatorY = lat => Math.log(Math.tan(Math.PI / 4 + (lat * RAD) / 2));
const Y_TOP = mercatorY(LAT_MAX);
const Y_BOTTOM = mercatorY(LAT_MIN);
const X_RANGE = (LNG_MAX - LNG_MIN) * RAD;
const Y_RANGE = Y_TOP - Y_BOTTOM;
const SCALE = Math.min((WIDTH - PADDING * 2) / X_RANGE, (HEIGHT - PADDING * 2) / Y_RANGE);
const X_OFFSET = (WIDTH - X_RANGE * SCALE) / 2;
const Y_OFFSET = (HEIGHT - Y_RANGE * SCALE) / 2;

export function projectLatLng(lat, lng) {
  return {
    x: X_OFFSET + (lng - LNG_MIN) * RAD * SCALE,
    y: Y_OFFSET + (Y_TOP - mercatorY(lat)) * SCALE
  };
}

